+fn cp(side: Side, climb: bool, lead: Lead, comp: Compensation) -> ContourParams {
+    ContourParams {
+        tool_diameter: 6.0,
+        stock_to_leave: 0.0,
+        clearance_z: 5.0,
+        retract_z: 2.0,
+        top_z: 0.0,
+        bottom_z: -2.0,
+        stepdown: 2.0,
+        feed: 500.0,
+        plunge_feed: 100.0,
