+        tab_count: 0,
+        tab_width: 0.0,
+        tab_height: 0.0,
+        entry: Entry3D::Plunge,
+        helix_radius: 1.0,
+        blend_turns: false,
+        links: Links { approach: Approach { compensation: comp, ..Approach::DEFAULT }, ..Links::PLANAR },
+    }
